const body = $input.first().json.body;
const type = body.type || 'booking';
const lang = (body.language || 'es').toLowerCase();
const name = body.patient_name || 'Paciente';
const doctor = body.doctor_name || '';
const specialty = body.specialty || '';
const date = body.date || '';
const time = body.time || '';
const apptId = body.appointment_id || '';
const phone = String(body.patient_phone || '');
const clinicPhone = '+34 91 345 17 57';
const clinicAddress = 'Calle Doctor Esquerdo 16, Madrid';

let message = '';

if (lang === 'es') {
  if (type === 'booking') {
    message = `✅ Cita confirmada
Paciente: ${name}
Doctor: ${doctor}
Especialidad: ${specialty}
📅 ${date} a las ${time}
🆔 ${apptId}
📍 ${clinicAddress}
Para cancelar llame al ${clinicPhone}`;
  } else if (type === 'cancel') {
    message = `❌ Cita cancelada
Paciente: ${name}
Doctor: ${doctor}
📅 ${date} a las ${time}
Su cita ha sido cancelada correctamente.
Clínica Masoumi | ${clinicPhone}`;
  } else if (type === 'reschedule') {
    message = `🔄 Cita reprogramada
Paciente: ${name}
Doctor: ${doctor}
📅 Nueva fecha: ${date} a las ${time}
🆔 ${apptId}
Clínica Masoumi | ${clinicPhone}`;
  }
} else {
  if (type === 'booking') {
    message = `✅ Appointment Confirmed
Patient: ${name}
Doctor: ${doctor}
Specialty: ${specialty}
📅 ${date} at ${time}
🆔 ${apptId}
📍 ${clinicAddress}
To cancel call ${clinicPhone}`;
  } else if (type === 'cancel') {
    message = `❌ Appointment Cancelled
Patient: ${name}
Doctor: ${doctor}
📅 ${date} at ${time}
Your appointment has been successfully cancelled.
Masoumi Clinic | ${clinicPhone}`;
  } else if (type === 'reschedule') {
    message = `🔄 Appointment Rescheduled
Patient: ${name}
Doctor: ${doctor}
📅 New date: ${date} at ${time}
🆔 ${apptId}
Masoumi Clinic | ${clinicPhone}`;
  }
}

return [{ json: { sms_message: message, to_phone: phone, patient_name: name, type } }];
